//! r460 — third-party STILL-PICTURE interop corpus: the AV1 image
//! items real-world AVIF / HEIF producers emit (a libheif-driven
//! encoder via `heif-enc` and ImageMagick, an SVT-AV1-driven encoder
//! through a black-box AVIF muxer, and `aomenc --allintra` IVF
//! output), each pinned by the SHA-256 of the pixels an independent
//! black-box reference decoder produced for it (cross-checked against
//! a second independent decoder at generation time). The AVIF /
//! HEIF-extracted items also carry the producer's `av1C` record so
//! the crate's record derivation is checked against real containers
//! (av1-avif §2.2.1: the record "shall match the Sequence Header OBU
//! in the AV1 Image Item Data") and the framework decoder's
//! extradata path is exercised with a real record.
//!
//! Every stream here is tool-generated from synthetic sources
//! (`testsrc2` / `mandelbrot` / gradients) — no third-party media.
//! The IVF bytes are embedded as hex so the test runs in per-crate CI
//! without the docs checkout.

use oxideav_av1::codec_config::Av1CodecConfig;
use oxideav_av1::decoder::decode_av1_spec;
use oxideav_av1::registry::{make_decoder, CODEC_ID_STR};
use oxideav_core::{CodecId, CodecParameters, Frame as CoreFrame, Packet, TimeBase};

fn unhex(s: &str) -> Vec<u8> {
    assert!(s.len() % 2 == 0, "hex literal must have even length");
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

const SHA256_K: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

fn sha256_hex(data: &[u8]) -> String {
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let mut msg = data.to_vec();
    let bit_len = (data.len() as u64) * 8;
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());
    for chunk in msg.chunks_exact(64) {
        let mut w = [0u32; 64];
        for (i, word) in chunk.chunks_exact(4).enumerate() {
            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }
        let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh) =
            (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA256_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }
    h.iter().map(|v| format!("{v:08x}")).collect()
}

/// Decode `ivf_hex` through the spec driver, check the frame count and
/// the SHA-256 of the concatenated output planes against the
/// independent decoder's digest; when the producer's `av1C` record is
/// given, check it against the in-band sequence header and decode the
/// bare item payload through the framework decoder fed that record.
fn check_still(name: &str, ivf_hex: &str, digest: &str, av1c_hex: Option<&str>) {
    let ivf = unhex(ivf_hex);
    let frames = decode_av1_spec(&ivf)
        .unwrap_or_else(|e| panic!("{name}: spec driver rejected the stream: {e:?}"));
    assert_eq!(frames.len(), 1, "{name}: one shown frame");
    let mut got = Vec::new();
    for p in &frames[0].planes {
        got.extend_from_slice(p);
    }
    assert_eq!(
        sha256_hex(&got),
        digest,
        "{name}: decoded pixels differ from the independent decoder (SHA-256 over {} bytes)",
        got.len()
    );
    let payload = oxideav_av1::encoder::IvfReader::new(&ivf)
        .expect("ivf")
        .read_all()
        .expect("records")
        .remove(0)
        .payload;
    if let Some(av1c_hex) = av1c_hex {
        let record = unhex(av1c_hex);
        let cfg = Av1CodecConfig::parse(&record).expect("producer av1C parses");
        let seq = oxideav_av1::obu::ObuIter::new(&payload)
            .filter_map(Result::ok)
            .find(|d| d.obu_type == oxideav_av1::obu::ObuType::SequenceHeader)
            .map(|d| oxideav_av1::sequence_header::parse_sequence_header(d.payload).expect("sh"))
            .expect("in-band sequence header");
        assert!(
            cfg.matches_sequence_header(&seq),
            "{name}: producer av1C {record:02x?} does not match the sequence header ({:?})",
            Av1CodecConfig::from_sequence_header(&seq)
        );
        // Producers write `chroma_sample_position = 2` for 4:2:2 /
        // 4:4:4 items although §5.5.2 codes no position there; the
        // byte comparison masks the field on those layouts.
        let mut ours = Av1CodecConfig::from_sequence_header(&seq).to_bytes();
        let mut theirs = record.clone();
        if !(cfg.chroma_subsampling_x && cfg.chroma_subsampling_y) {
            ours[2] &= !3;
            theirs[2] &= !3;
        }
        assert_eq!(ours, theirs, "{name}: record bytes");
        let mut params = CodecParameters::video(CodecId::new(CODEC_ID_STR));
        params.extradata = record;
        let mut dec = make_decoder(&params).expect("framework decoder");
        dec.send_packet(&Packet::new(0, TimeBase::new(1, 1), payload))
            .unwrap_or_else(|e| panic!("{name}: framework decode: {e}"));
        let CoreFrame::Video(v) = dec.receive_frame().expect("frame") else {
            panic!("{name}: video frame expected");
        };
        let mut fw = Vec::new();
        for p in v.image_planes() {
            fw.extend_from_slice(&p.data);
        }
        assert_eq!(sha256_hex(&fw), digest, "{name}: framework decoder output");
    }
}

/// libheif/aom via heif-enc — 256x130 8-bit 4:2:0 q60 (non-multiple-of-8 height) (1886 B).
#[test]
fn still_he_t257_q60_primary() {
    check_still(
        "he_t257_q60_primary",
        "",
        "9fd9f24a48833695620c52572c6862825176c8e7ecef14f6c8f7c3ca0aa8e393",
        Some("81000c00"),
    );
}

